'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/bulk-transfers — batch payouts to many recipients at once.
 */
class BulkTransfers {
  constructor(client) {
    this.client = client;
  }

  /**
   * List bulk transfer batches.
   * @param {object} [params]
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/bulk-transfers', params));
  }

  /**
   * Create a bulk transfer batch.
   * @param {object} params
   * @param {string} params.label
   * @param {string} params.currency
   * @param {Array}  params.items          [{ operator_code, recipient_phone, amount, note?, external_ref? }, ...]
   * @param {string} [params.external_ref]
   * @param {object} [params.metadata]
   */
  create(params) {
    return this.client.request('POST', '/v1/bulk-transfers', params);
  }

  /**
   * Retrieve a bulk transfer batch by ID.
   * @param {string} id
   */
  retrieve(id) {
    return this.client.request('GET', `/v1/bulk-transfers/${encodeURIComponent(id)}`);
  }

  /**
   * List the individual items/recipients within a batch.
   * @param {string} id
   * @param {object} [params]
   */
  items(id, params) {
    return this.client.request('GET', withQuery(`/v1/bulk-transfers/${encodeURIComponent(id)}/items`, params));
  }

  /**
   * Start processing a batch (dispatch the individual payouts).
   * @param {string} id
   */
  process(id) {
    return this.client.request('POST', `/v1/bulk-transfers/${encodeURIComponent(id)}/process`);
  }

  /**
   * Cancel/delete a batch (only possible before it has been processed).
   * @param {string} id
   */
  delete(id) {
    return this.client.request('DELETE', `/v1/bulk-transfers/${encodeURIComponent(id)}`);
  }
}

module.exports = BulkTransfers;
